      "file": "core/pipeline/cycle-orchestrator.sh",
      "category": "hot-path overhead",
      "severity": "low",
      "line": 2478,
      "message": "Every cycle iteration on every run (including fresh runs) now pays an extra `locked_state_update` (flock + jq subprocess + atomic rename) at iteration start, even though for a completed iteration the end-of-iter write (`_cycle_state_write_iter_atomic`) already overwrites `current_iter` with the same value, making the start write pure overhead for the common case.",
      "quote": "_cycle_state_write_iter_start \"$state_file\" \"$cycle_id\" \"$iter\" || true",
      "introduced": true,
      "fix": "code"
    }
  ]
}
